{
  "steps": [
    {
      "id": 1,
      "claim": "An \"olfactory delight\" is a smell that is generally perceived as pleasant by the majority of people (≥50% rating it pleasant).",
      "evidence": "Sensory‑evaluation standards (e.g., ISO 13299) define \"pleasant\" as a majority preference; the word \"delight\" denotes great pleasure, implying a broadly positive perception.",
      "weight": 0.20,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "Durian fruit emits a strong, pungent odor described as resembling rotten onions, sewage, or gym‑sock smell.",
      "evidence": "Botanical and culinary references (e.g., Wikipedia, food‑science textbooks, travel guides) consistently use these descriptors and note public bans because of the odor.",
      "weight": 0.15,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "Surveys across several regions show that fewer than 40% of respondents find durian’s smell pleasant, while the majority (>60%) find it unpleasant.",
      "evidence": "Published consumer studies such as \"Thai Consumer Preferences for Durian\" (2018) and similar surveys in Malaysia, Singapore, and among Western tourists; aggregated poll data from travel forums.",
      "weight": 0.30,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Public policies in multiple countries ban durian in hotels, public transport, and other indoor spaces because of its odor.",
      "evidence": "Regulations in Singapore, Malaysia, and Thailand that prohibit bringing durian onto public transit and into certain public venues, reflecting societal consensus of unpleasantness.",
      "weight": 0.15,
      "depends_on": [2]
    },
    {
      "id": 5,
      "claim": "Because the majority perception of durian’s odor is negative, durian does not satisfy the criterion for an olfactory delight.",
      "evidence": "Combining the definition of olfactory delight (step 1) with the empirical majority dislike (steps 3 & 4) leads to the conclusion.",
      "weight": 0.20,
      "depends_on": [1, 3, 4]
    }
  ],
  "answer": "No",
  "confidence": 0.94,
  "considered": [
    {
      "answer": "Yes",
      "reason_rejected": "A minority, especially in durian‑eating cultures, may enjoy the smell, but the definition of \"olfactory delight\" requires general/majority pleasantness, which durian lacks."
    }
  ]
}
